from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    # A same-color diagonal pair with the opposite corners at background
    # defines a diagonal ray, extended both ways until an edge or obstruction.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                rr, cc = r + dr, c + dc
                if not (0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color):
                    continue
                if grid[r][c + dc] != bg or grid[r + dr][c] != bg:
                    continue
                x, y = r - dr, c - dc
                while 0 <= x < h and 0 <= y < w and grid[x][y] == bg:
                    out[x][y] = color
                    x -= dr
                    y -= dc
                x, y = rr + dr, cc + dc
                while 0 <= x < h and 0 <= y < w and grid[x][y] == bg:
                    out[x][y] = color
                    x += dr
                    y += dc
    return out

